result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "findlite.py", "content": "#!/usr/bin/env python3
"""findlite.py - a minimal `find` clone supporting a subset of predicates.

Usage: findlite.py DIR [-name GLOB] [-type f|d] [-size +N|-N]
                       [-newer FILE] [-maxdepth N]

All given predicates must match (logical AND). Matches are printed sorted.
"""

import argparse
import fnmatch
import os
import sys


def parse_args(argv):
    p = argparse.ArgumentParser(prog="findlite", description="minimal find")
    p.add_argument("dir", help="directory to search")
    p.add_argument("-name", dest="name", metavar="GLOB",
                   help="match basename against glob")
    p.add_argument("-type", dest="type", choices=["f", "d"], metavar="T",
                   help="match regular files (f) or directories (d)")
    p.add_argument("-size", dest="size", metavar="N",
                   help="file size in bytes: +N (greater), -N (less), N (exact)")
    p.add_argument("-newer", dest="newer", metavar="FILE",
                   help="mtime strictly newer than FILE's mtime")
    p.add_argument("-maxdepth", dest="maxdepth", type=int, metavar="N",
                   help="limit traversal depth (0 = start dir only)")
    return p.parse_args(argv)


def size_predicate(size_spec):
    if size_spec.startswith("+"):
        op, n = "gt", int(size_spec[1:])
    elif size_spec.startswith("-"):
        op, n = "lt", int(size_spec[1:])
    else:
        op, n = "eq", int(size_spec)
    return lambda st: {
        "gt": st.st_size > n,
        "lt": st.st_size < n,
        "eq": st.st_size == n,
    }[op]


def make_predicates(args):
    preds = []
    if args.name is not None:
        preds.append(lambda path, st, g=args.name: fnmatch.fnmatch(
            os.path.basename(path), g))
    if args.type is not None:
        want_dir = args.type == "d"
        import stat as statmod
        preds.append(lambda path, st, d=want_dir:
                     statmod.S_ISDIR(st.st_mode) == d)
    if args.size is not None:
        sp = size_predicate(args.size)
        preds.append(lambda path, st, _sp=sp: _sp(st))
    if args.newer is not None:
        ref_mtime = os.stat(args.newer).st_mtime
        preds.append(lambda path, st, m=ref_mtime: st.st_mtime > m)
    return preds


def walk(root, maxdepth):
    """Yield (depth, path) for root and all descendants up to maxdepth."""
    yield 0, root
    if maxdepth is not None and maxdepth == 0:
        return
    for dirpath, dirnames, filenames in os.walk(root):
        rel = os.path.relpath(dirpath, root)
        depth = 0 if rel == "." else rel.count(os.sep) + 1
        if maxdepth is not None and depth + 1 > maxdepth:
            dirnames[:] = []
            continue
        names = sorted(dirnames + filenames)
        for name in names:
            yield depth + 1, os.path.join(dirpath, name)


def main(argv=None):
    args = parse_args(argv if argv is not None else sys.argv[1:])
    try:
        preds = make_predicates(args)
        results = []
        for depth, path in walk(args.dir, args.maxdepth):
            try:
                st = os.lstat(path)
            except OSError:
                continue
            if all(p(path, st) for p in preds):
                results.append(path)
    except OSError as e:
        print(f"findlite: error: {e}", file=sys.stderr)
        return 1
    for path in sorted(results):
        print(path)
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
